mapper.insert:
INSERT dbo.Chapter (StoryId, VolumeId, ChapterNo, Title, Content, WordCount)
SELECT #{storyId}, #{volumeId, jdbcType=INTEGER}, ISNULL(MAX(x.ChapterNo), 0) + 1,
       #{title}, #{content}, #{wordCount}
FROM dbo.Chapter x WITH (UPDLOCK, HOLDLOCK)
WHERE x.StoryId = #{storyId}

mapper.select:
SELECT DISTINCT StoryId
FROM dbo.Chapter
WHERE Status = 'PUBLISHED' AND IsDeleted = 0 AND PublishedAt >= #{since}
